package com.bank.spark.model;

// Describes a join: side sizes and whether it is an equality join.
public class JoinInput {
    private final String leftName;
    private final long leftBytes;
    private final String rightName;
    private final long rightBytes;
    private final boolean equiJoin;
    private final boolean rightFitsPerPartitionMemory;

    public JoinInput(String leftName, long leftBytes, String rightName, long rightBytes,
                     boolean equiJoin, boolean rightFitsPerPartitionMemory) {
        this.leftName = leftName;
        this.leftBytes = leftBytes;
        this.rightName = rightName;
        this.rightBytes = rightBytes;
        this.equiJoin = equiJoin;
        this.rightFitsPerPartitionMemory = rightFitsPerPartitionMemory;
    }

    public long smallerSideBytes() { return Math.min(leftBytes, rightBytes); }
    public String leftName() { return leftName; }
    public String rightName() { return rightName; }
    public boolean isEquiJoin() { return equiJoin; }
    public boolean rightFitsPerPartitionMemory() { return rightFitsPerPartitionMemory; }
}
