package com.bank.spark.service;

import com.bank.spark.model.JoinInput;

// Applies Spark's join-strategy selection rules.
public class JoinStrategySelector {

    private final long broadcastThresholdBytes;

    public JoinStrategySelector(long broadcastThresholdBytes) {
        this.broadcastThresholdBytes = broadcastThresholdBytes;
    }

    public String choose(JoinInput j) {
        if (!j.isEquiJoin()) {
            // No key to hash/sort on → nested loop (broadcast the small side).
            return "Broadcast Nested Loop Join (non-equi condition)";
        }
        if (j.smallerSideBytes() <= broadcastThresholdBytes) {
            return "Broadcast Hash Join (small side " + j.smallerSideBytes()
                    + " B <= threshold " + broadcastThresholdBytes + " B; no shuffle of large side)";
        }
        if (j.rightFitsPerPartitionMemory()) {
            return "Shuffle Hash Join (both shuffled; hash table on smaller side per partition)";
        }
        return "Shuffle Sort Merge Join (both shuffled + sorted by key, then merge)";
    }
}
