package com.bank.spark;

import com.bank.spark.model.JoinInput;
import com.bank.spark.service.JoinStrategySelector;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class JoinStrategyDemo {

    private static final Logger log = Logger.getLogger(JoinStrategyDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        JoinStrategySelector selector = new JoinStrategySelector(10 * 1024 * 1024); // 10 MB

        // 1) transactions (large) JOIN branches (tiny) on branchId → BHJ
        JoinInput bhj = new JoinInput("transactions", 50_000_000_000L, "branches", 4_000L, true, false);
        log.info("transactions ⋈ branches -> " + selector.choose(bhj));

        // 2) transactions (large) JOIN accounts (large) on accountId → SSMJ
        JoinInput ssmj = new JoinInput("transactions", 50_000_000_000L, "accounts", 8_000_000_000L, true, false);
        log.info("transactions ⋈ accounts -> " + selector.choose(ssmj));

        // 3) both large but right fits per-partition memory → SHJ
        JoinInput shj = new JoinInput("trades", 20_000_000_000L, "positions", 2_000_000_000L, true, true);
        log.info("trades ⋈ positions -> " + selector.choose(shj));

        // 4) non-equi: price within 5% → BNLJ
        JoinInput bnlj = new JoinInput("trades", 1_000_000L, "priceBands", 5_000L, false, false);
        log.warning("trades ⋈ priceBands (within 5%) -> " + selector.choose(bnlj));

        log.info("AQE may switch SSMJ to BHJ at runtime if a side turns out small after filtering.");
    }
}

